-- Generated from dump.sql → app_facilities + sports + courts/prices
BEGIN;
-- Clear proximity catalog-related rows
DELETE FROM app_slots;
DELETE FROM app_bookings;
DELETE FROM app_price_list;
DELETE FROM app_coupons;
DELETE FROM app_user_coupons;
DELETE FROM app_facility_sports;
DELETE FROM app_facilities;

-- Upsert sports from dump sports_categories
SELECT setval(pg_get_serial_sequence('app_sports','id'), GREATEST((SELECT MAX(id) FROM app_sports), 1));

-- Facilities
SELECT setval(pg_get_serial_sequence('app_facilities','id'), GREATEST((SELECT MAX(id) FROM app_facilities), 1));

-- Facility sports

-- Price list from sport_schedule + sub_facilities
COMMIT;
SELECT 'app_facilities' t, count(*)::text n FROM app_facilities UNION ALL SELECT 'app_facility_sports', count(*)::text FROM app_facility_sports UNION ALL SELECT 'app_price_list', count(*)::text FROM app_price_list;
